export type Priority = "Low" | "Medium" | "High";
export type TaskStatus = "Open" | "In Progress" | "Completed";
export type EmployeeStatus = "Active" | "Pending Start" | "Former" | "On Assignment";
export type RequestStatus = "Open" | "In Progress" | "Resolved";
export type RequestType =
  | "Returned Check"
  | "Direct Deposit Change"
  | "W-2 Request"
  | "Employment Verification"
  | "Address Change"
  | "General HR";

export interface Company {
  code: string;
  name: string;
  location: string;
  notes: string;
}

export interface CompanyHistoryEntry {
  companyCode: string;
  position?: string;
  from: string;
  to?: string;
  note?: string;
}

export interface NoteEntry {
  at: string;
  author?: string;
  text: string;
}

export interface Employee {
  id: string;
  employeeNumber: string;
  name: string;
  phone: string;
  email: string;
  address: string;
  emergencyContact: string;
  status: EmployeeStatus;
  position: string;
  payRate: number;
  hireDate: string;
  companyCode: string;
  currentAssignment: string;
  directDeposit: "Active" | "Pending" | "None";
  notes: string;
  scheduledStartDate?: string;
  companyHistory?: CompanyHistoryEntry[];
  noteLog?: NoteEntry[];
}


export interface Task {
  id: string;
  title: string;
  dueDate: string;
  priority: Priority;
  assignedEmployeeId?: string;
  companyCode?: string;
  status: TaskStatus;
  notes: string;
  completedAt?: string;
}

export interface EmployeeRequest {
  id: string;
  employeeId: string;
  companyCode: string;
  type: RequestType;
  submittedAt: string;
  priority: Priority;
  status: RequestStatus;
  assignedTo: string;
  notes: string;
  completedAt?: string;
}

export interface PayrollIssue {
  id: string;
  employeeId: string;
  companyCode: string;
  issue: string;
  amount?: number;
  reportedAt: string;
  status: "Open" | "Resolved";
}

